// Largest-remainder allocation preserves integer totals across every chart bucket.
export function allocateCounts(total: number, weights: readonly number[]) {
  const sum = weights.reduce((a, b) => a + b, 0);
  if (!sum) return weights.map(() => 0);
  const exact = weights.map((weight) => (total * weight) / sum);
  const values = exact.map(Math.floor);
  const remainder = total - values.reduce((a, b) => a + b, 0);
  exact
    .map((v, index) => ({ index, fraction: v - values[index] }))
    .sort((a, b) => b.fraction - a.fraction || a.index - b.index)
    .slice(0, remainder)
    .forEach(({ index }) => values[index]++);
  return values;
}

