// Current-window totals and negative counts are exactly reproducible from the original record list.
export function observationSeries(period = "24小时") {
  const currentNegative = articles.filter((a) => a.sentiment === "负面").length;
  const daily = [...historicalCounts, observationTotal];
  const negative = [...historicalNegative, currentNegative];
  const size = period === "24小时" ? 24 : period === "7天" ? 7 : 30;
  return Array.from({ length: size }, (_, index) => {
    const date = new Date(Date.UTC(2026, 10, 3, 14, 30));
    if (period === "24小时")
      date.setUTCHours(date.getUTCHours() - size + 1 + index);
    else date.setUTCDate(date.getUTCDate() - size + 1 + index);
    const records =
      period === "24小时"
        ? articles.filter((a) => observationBucket(a) === index)
        : [];
    return {
      value: period === "24小时" ? records.length : daily[30 - size + index],
      negative:
        period === "24小时"
          ? records.filter((a) => a.sentiment === "负面").length
          : negative[30 - size + index],
      label:
        period === "24小时"
          ? `${String(date.getUTCHours()).padStart(2, "0")}:30`
          : `${date.getUTCMonth() + 1}/${date.getUTCDate()}`,
    };
  });
}

// Every heatmap cell aggregates the same two-hour document buckets as the topic detail.
export function domainActivity() {
  return [...new Set(topics.map((t) => t.category))].map((category) => {
    const rows = topics
      .filter((t) => t.category === category)
      .map((t) => t.trend);
    return {
      category,
      values: Array.from({ length: 12 }, (_, i) =>
        rows.reduce((sum, row) => sum + row[i], 0),
      ),
    };
  });
}

// Source withdrawal changes availability, while historical report membership remains auditable.
export function evidenceSummary(state: MobileState) {
  const records = articles.filter((a) => a.topicId === focusTopicId);
  return {
    records,
    available: records.filter(
      (a) => !state.withdrawn || a.id !== controlledDocument,
    ),
    affected: state.reports.filter(
      (r) => r.stale && r.evidenceIds.includes(controlledDocument),
    ),
  };
}

